```go
package main

import "fmt"

type Counter int

func (c Counter) Value() int { return int(c) }
func (c *Counter) Add()      { *c++ }

type Reader interface{ Value() int }
type Incrementer interface{ Add() }

func main() {
    var counter Counter
    var reader Reader = counter
    var incrementer Incrementer = &counter
    incrementer.Add()
    fmt.Println(reader.Value(), counter.Value())
}
```
`Counter` satisfies `Reader`, while only `*Counter` satisfies `Incrementer`. The saved `reader` contains a value copy, so it still reports zero.

```go
package main

import "fmt"

type Timer int

func (t *Timer) Reset() { *t = 0 }

type Resetter interface{ Reset() }

func main() {
    timer := Timer(5)
    timer.Reset()
    var resetter Resetter = &timer
    resetter.Reset()
    fmt.Println(timer)
    // var invalid Resetter = timer // Timer lacks Reset in its method set.
}
```
The value call works through automatic addressing. The interface must receive `&timer`, whose concrete type is `*Timer`.

```go
package main

import (
    "fmt"
    "strings"
)

type UserID string

func (id UserID) Valid() bool {
    return strings.HasPrefix(string(id), "u-") && len(id) > 2
}

func main() {
    id := UserID("u-42")
    fmt.Println(id.Valid(), string(id))
}
```
`UserID` can have local methods even though its underlying type is `string`; ordinary strings do not gain those methods.
